#!/usr/bin/env python3
"""
Wires practitioner billing to Stripe.

Stripe, not RevenueCat. RevenueCat exists to deal with Apple on behalf of app
users; practitioners never open the app, so putting them through it would mean
paying a cut for nothing and handing them no tax invoice.

  new   src/lib/stripe.ts                                   REST calls + webhook signature check
        src/components/therapist-billing-button.tsx
        src/app/api/therapists/billing/checkout/route.ts    checkout, or the portal if already paying
        src/app/api/stripe/webhook/route.ts                 Stripe tells us what changed

  edit  src/lib/therapists.ts                               two Stripe columns on the type
        src/app/therapists/dashboard/page.tsx               the billing button
        .env.example                                        Stripe keys

No new npm package. Stripe is three form-encoded POSTs and an HMAC, so this
talks to their REST API directly rather than adding a dependency.

The database columns are already live.

Run from anywhere:  python3 add-stripe-billing.py
"""

import base64
import json
import sys
from pathlib import Path

ENV_BLOCK = """
# --- Stripe (practitioners only) -------------------------------------------
# The $30/month practitioner listing. Completely separate from RevenueCat,
# which exists to deal with Apple for app users. Practitioners never open the
# app, so they never touch RevenueCat and Apple never touches this money.
STRIPE_SECRET_KEY=
STRIPE_PRICE_ID=
STRIPE_WEBHOOK_SECRET=
# Set to true only AFTER switching Stripe Tax on in the Stripe dashboard.
# Without that, Stripe rejects the checkout and the practitioner sees an error
# they cannot act on.
STRIPE_AUTOMATIC_TAX=false
"""

BLOB = '{"src/lib/stripe.ts": "", "src/lib/therapists.ts": "", "src/components/therapist-billing-button.tsx": "", "src/app/therapists/dashboard/page.tsx": "", "src/app/api/therapists/billing/checkout/route.ts": "", "src/app/api/stripe/webhook/route.ts": ""}'

FILES = json.loads(BLOB)


def find_repo() -> Path:
    seeds = [Path(__file__).resolve().parent, Path.cwd()]
    for seed in seeds:
        for root in [seed, *seed.parents]:
            if (root / "src" / "lib" / "therapists.ts").is_file():
                return root
    sys.exit(
        "Could not find src/lib/therapists.ts above this script.\n"
        "Run add-therapists.py first, then put this file in ~/Documents/mentara-v2."
    )


def main() -> None:
    root = find_repo()

    for rel, encoded in sorted(FILES.items()):
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        existed = path.is_file()
        path.write_bytes(base64.b64decode(encoded))
        print(f"  {'~' if existed else '+'} {rel}")

    env = root / ".env.example"
    if env.is_file():
        text = env.read_text(encoding="utf-8")
        if "STRIPE_SECRET_KEY" not in text:
            env.write_text(text.rstrip("\n") + "\n" + ENV_BLOCK, encoding="utf-8")
            print("  ~ .env.example")

    print("\nStripe dashboard, once:")
    print("  1. Product 'Mentara practitioner listing', recurring, A$30/month")
    print("     -> copy the PRICE id (price_...), not the product id")
    print("  2. Developers -> API keys -> copy the secret key (sk_...)")
    print("  3. Developers -> Webhooks -> add endpoint")
    print("       URL:    https://<your-domain>/api/stripe/webhook")
    print("       Events: checkout.session.completed,")
    print("               customer.subscription.updated,")
    print("               customer.subscription.deleted,")
    print("               invoice.payment_failed")
    print("     -> copy the signing secret (whsec_...)")
    print("\nThen in Vercel (Production and Preview):")
    print("  STRIPE_SECRET_KEY, STRIPE_PRICE_ID, STRIPE_WEBHOOK_SECRET")
    print("\nThen:")
    print('  git add -A && git commit -m "Practitioner billing on Stripe"')
    print("  git push")


if __name__ == "__main__":
    main()
